cat << 'EOF' > /tmp/patch_pom.js
const fs = require('fs');
const filepath = 'neo4j-cypher-dsl-parser/pom.xml';
let content = fs.readFileSync(filepath, 'utf8');

const targetStr = `\t\t\t<plugin>
\t\t\t\t<groupId>com.github.siom79.japicmp</groupId>
\t\t\t\t<artifactId>japicmp-maven-plugin</artifactId>
\t\t\t</plugin>`;

const replacementStr = `\t\t\t<plugin>
\t\t\t\t<groupId>com.github.siom79.japicmp</groupId>
\t\t\t\t<artifactId>japicmp-maven-plugin</artifactId>
\t\t\t\t<configuration combine.self="append">
\t\t\t\t\t<parameter>
\t\t\t\t\t\t<excludes>
\t\t\t\t\t\t\t<exclude>org.neo4j.cypherdsl.parser.internal</exclude>
\t\t\t\t\t\t\t<exclude>org.neo4j.cypherdsl.parser.internal..*</exclude>
\t\t\t\t\t\t\t<exclude>org.neo4j.cypherdsl.parser.internal.*</exclude>
\t\t\t\t\t\t</excludes>
\t\t\t\t\t</parameter>
\t\t\t\t</configuration>
\t\t\t</plugin>`;

// Normalize line endings
const normalizedContent = content.replace(/\r\n/g, '\n');
const normalizedTarget = targetStr.replace(/\r\n/g, '\n');
const normalizedReplacement = replacementStr.replace(/\r\n/g, '\n');

if (!normalizedContent.includes(normalizedTarget)) {
    console.error('Target plugin configuration not found!');
    process.exit(1);
}

const updatedContent = normalizedContent.replace(normalizedTarget, normalizedReplacement);
fs.writeFileSync(filepath, updatedContent, 'utf8');
console.log('Success!');
EOF
